content.text:
{
  "name": "Yoctopuce 网络接口配置组件",
  "name_en": "Yoctopuce Network Interface Configuration Component",
  "manufacturer": "Yoctopuce",
  "description": "这是一个非实体的软件功能组件，用于访问和配置带内置网络接口的 Yoctopuce 设备的 TCP/IP 参数。它可用于管理 IP、DNS、NTP、HTTP 回调、发现广播、网页服务端口以及网络连通性测试等网络相关设置。",
  "description_en": "This is a non-physical software function component used to access and configure TCP/IP parameters of Yoctopuce devices with a built-in network interface. It is used to manage network-related settings such as IP, DNS, NTP, HTTP callbacks, discovery protocols, web service port, and connectivity testing.",
  "tag_hints": [
    "Yoctopuce",
    "network interface configuration",
    "IP and DHCP settings",
    "HTTP callback",
    "embedded web UI",
    "DNS and NTP configuration",
    "device discovery",
    "network connectivity test"
  ],
  "actions": [
    {
      "action_name": "auto-set_ipConfig",
      "description": "设置 IP 配置",
      "description_en": "set IP configuration"
    },
    {
      "action_name": "auto-set_primaryDNS",
      "description": "设置主 DNS 服务器",
      "description_en": "set primary DNS server"
    },
    {
      "action_name": "auto-set_secondaryDNS",
      "description": "设置备用 DNS 服务器",
      "description_en": "set secondary DNS server"
    },
    {
      "action_name": "auto-set_ntpServer",
      "description": "设置 NTP 服务器",
      "description_en": "set NTP server"
    },
    {
      "action_name": "auto-set_userPassword",
      "description": "设置用户密码",
      "description_en": "set user password"
    },
    {
      "action_name": "auto-set_adminPassword",
      "description": "设置管理员密码",
      "description_en": "set admin password"
    },
    {
      "action_name": "auto-set_httpPort",
      "description": "设置 HTTP 服务端口",
      "description_en": "set HTTP service port"
    },
    {
      "action_name": "auto-set_defaultPage",
      "description": "设置默认网页",
      "description_en": "set default web page"
    },
    {
      "action_name": "auto-set_discoverable",
      "description": "设置网络可发现性",
      "description_en": "set network discoverability"
    },
    {
      "action_name": "auto-set_wwwWatchdogDelay",
      "description": "设置 WWW 看门狗延迟",
      "description_en": "set WWW watchdog delay"
    },
    {
      "action_name": "auto-set_callbackUrl",
      "description": "设置回调 URL",
      "description_en": "set callback URL"
    },
    {
      "action_name": "auto-set_callbackMethod",
      "description": "设置回调 HTTP 方法",
      "description_en": "set callback HTTP method"
    },
    {
      "action_name": "auto-set_callbackEncoding",
      "description": "设置回调编码方式",
      "description_en": "set callback encoding"
    },
    {
      "action_name": "auto-set_callbackCredentials",
      "description": "设置回调认证凭据",
      "description_en": "set callback credentials"
    },
    {
      "action_name": "auto-callbackLogin",
      "description": "登录回调端点并保存回调认证凭据",
      "description_en": "log in to the callback endpoint and save callback credentials"
    },
    {
      "action_name": "auto-set_callbackInitialDelay",
      "description": "设置回调初始延迟",
      "description_en": "set initial callback delay"
    },
    {
      "action_name": "auto-set_callbackSchedule",
      "description": "设置回调计划",
      "description_en": "set callback schedule"
    },
    {
      "action_name": "auto-set_callbackMinDelay",
      "description": "设置最小回调间隔",
      "description_en": "set minimum callback delay"
    },
    {
      "action_name": "auto-set_callbackMaxDelay",
      "description": "设置最大回调间隔",
      "description_en": "set maximum callback delay"
    },
    {
      "action_name": "auto-useDHCP",
      "description": "将网络接口配置为使用 DHCP，并设置回退网络参数",
      "description_en": "configure the network interface to use DHCP with fallback network settings"
    },
    {
      "action_name": "auto-useDHCPauto",
      "description": "将网络接口配置为自动使用 DHCP",
      "description_en": "configure the network interface to use DHCP automatically"
    },
    {
      "action_name": "auto-useStaticIP",
      "description": "将网络接口配置为使用静态 IP",
      "description_en": "configure the network interface to use a static IP address"
    },
    {
      "action_name": "auto-ping",
      "description": "从模块发起主机连通性测试",
      "description_en": "ping a host from the module to test connectivity"
    },
    {
      "action_name": "auto-triggerCallback",
      "description": "立即触发一次 HTTP 回调",
      "description_en": "trigger an HTTP callback immediately"
    },
    {
      "action_name": "auto-set_periodicCallbackSchedule",
      "description": "设置周期性回调计划",
      "description_en": "define a periodic callback schedule"
    },
    {
      "action_name": "auto-nextNetwork",
      "description": "枚举下一个网络接口对象",
      "description_en": "enumerate the next network interface object"
    }
  ]
}

